create table public.expenses (id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id) on delete cascade,crop_cycle_id uuid not null references public.crop_cycles(id) on delete cascade,expense_date date not null default current_date,category text not null check(category in ('labor','seed','fertilizer','pesticide','machinery','irrigation','fuel','transport','other')),amount numeric(14,2) not null check(amount>0),description text,created_at timestamptz not null default now());
create table public.harvests (id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id) on delete cascade,crop_cycle_id uuid not null references public.crop_cycles(id) on delete cascade,harvest_date date not null,quantity numeric(14,3) not null check(quantity>0),unit text not null check(unit in ('kg','ton','maund','bag','unit')),grade text,notes text,created_at timestamptz not null default now());
create index expenses_farm_id_idx on public.expenses(farm_id);create index expenses_crop_cycle_id_idx on public.expenses(crop_cycle_id);create index expenses_date_idx on public.expenses(expense_date);create index harvests_farm_id_idx on public.harvests(farm_id);create index harvests_crop_cycle_id_idx on public.harvests(crop_cycle_id);create index harvests_date_idx on public.harvests(harvest_date);
alter table public.expenses enable row level security;alter table public.harvests enable row level security;
create policy "owners select expenses" on public.expenses for select to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())));
create policy "owners insert expenses" on public.expenses for insert to authenticated with check(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())) and exists(select 1 from public.crop_cycles c where c.id=crop_cycle_id and c.farm_id=farm_id));
create policy "owners update expenses" on public.expenses for update to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid()))) with check(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())) and exists(select 1 from public.crop_cycles c where c.id=crop_cycle_id and c.farm_id=farm_id));
create policy "owners delete expenses" on public.expenses for delete to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())));
create policy "owners select harvests" on public.harvests for select to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())));
create policy "owners insert harvests" on public.harvests for insert to authenticated with check(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())) and exists(select 1 from public.crop_cycles c where c.id=crop_cycle_id and c.farm_id=farm_id));
create policy "owners update harvests" on public.harvests for update to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid()))) with check(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())) and exists(select 1 from public.crop_cycles c where c.id=crop_cycle_id and c.farm_id=farm_id));
create policy "owners delete harvests" on public.harvests for delete to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())));
grant select,insert,update,delete on public.expenses,public.harvests to authenticated;